cd /app; cat > /tmp/r.py <<'E'
import os,sys
R=int(sys.argv[1]);svc=sys.argv[2];env=sys.argv[3];host=sys.argv[4]
def get(p):
    rel=os.path.relpath(p,'/app/config')
    for r in range(R+1,420):
        q=f'/app/config-history/r{r:04d}/prev/{rel}'
        if os.path.exists(q): return open(q).read()
    return open(p).read()
cfg={}
def read(p,top_only_file=False,isserv=False):
    sec=None
    for ln in get(p).splitlines() if not isserv else open(p).read().splitlines():
        ln=ln.strip()
        if not ln or ln.startswith('#'):continue
        if ln.startswith('['):
            sec=ln[1:-1].strip();continue
        k,_,v=[x.strip() for x in ln.partition('=')]
        if k=='include':
            if sec is None:
                read(os.path.normpath(os.path.join(os.path.dirname(p),v.replace('${env}',env).replace('${host}',host))))
            continue
        if sec is None or sec==svc:
            cfg[k]=v; 
            if k in('admin_port','port_base','port_offset','enabled'):print(k,v,p,sec)
read(f'/app/services/{svc}/service.conf',isserv=True)
print(cfg)
